const fm = n => { if (n == null) return "—"; if (Math.abs(n) >= 1e6) return "$"+(n/1e6).toFixed(1)+"M"; if (Math.abs(n) >= 1e3) return "$"+(n/1e3).toFixed(1)+"K"; return "$"+Math.round(n); };
const fc = n => n != null ? "$"+n.toLocaleString(undefined,{maximumFractionDigits:0}) : "—";
const pt = n => n != null ? n.toFixed(1)+"%" : "—";
const rx = n => n != null ? n.toFixed(2)+"x" : "—";
const dlt = (a,b) => b > 0 ? ((a-b)/b*100) : 0;
const DB = ({v,inv}) => { const c = v >= 0 ? (inv?T.rd:T.gn) : (inv?T.gn:T.rd); return <span style={{fontSize:10,fontWeight:600,color:c}}>{v>=0?"+":""}{v.toFixed(1)}%</span>; };
const Spark = ({data,color,w=48,h=14}) => { if (!data||data.length<2) return null; const mn=Math.min(...data),mx=Math.max(...data),rng=mx-mn||1; const pts=data.map((v,i)=>`${(i/(data.length-1))*w},${h-((v-mn)/rng)*(h-2)-1}`).join(" "); return <svg width={w} height={h}><polyline points={pts} fill="none" stroke={color} strokeWidth={1.5} strokeLinecap="round"/></svg>; };
const acC = v => !v?T.t4:v<15?T.gn:v<25?T.am:T.rd;
const roC = v => !v?T.t4:v>6?T.gn:v>3.5?T.am:T.rd;
const coC = v => v==null?T.t4:v>0?T.gn:T.rd;
const nbC = v => !v?T.t4:v>5?T.gn:v>2.5?T.am:T.rd;
