function fatigueScore(ad){ let s=0;s+=Math.min(30,Math.max(0,(ad.age-7)*2.5));if(ad.hk!=null)s+=Math.min(30,Math.max(0,(35-ad.hk)*2));if(ad.freq!=null)s+=Math.min(20,Math.max(0,(ad.freq-2.5)*10));if(ad.cpa)s+=Math.min(20,Math.max(0,(ad.cpa-80)*0.25));return Math.round(Math.min(100,s));}
function FatigueBar({score}){const c=score>60?T.rd:score>35?T.am:T.gn;return <div style={{display:"flex",alignItems:"center",gap:3}}><div style={{width:28,height:4,background:T.bd,borderRadius:2,overflow:"hidden"}}><div style={{width:score+"%",height:"100%",background:c,borderRadius:2}}/></div><span style={{fontSize:9,fontWeight:600,color:c}}>{score}</span></div>;}
function BudgetBar({sp,bud,color}){if(!bud)return <span style={{fontSize:8,color:T.t4}}>—</span>;const p=Math.min(sp/bud*100,100);return <div style={{display:"flex",alignItems:"center",gap:3}}><div style={{width:28,height:4,background:T.bd,borderRadius:2,overflow:"hidden"}}><div style={{width:p+"%",height:"100%",background:p>95?T.rd:p>80?color:T.t4,borderRadius:2}}/></div><span style={{fontSize:8,color:p>95?T.rd:T.t3}}>{Math.round(p)}%</span></div>;}
function MC({label,value,sub,color,delta:d,inv}){return <div style={{padding:"8px 10px",background:T.cd,borderRadius:6,border:"1px solid "+T.bd}}><div style={{fontSize:8,color:T.t3,textTransform:"uppercase",letterSpacing:.4}}>{label}</div><div style={{display:"flex",alignItems:"baseline",gap:4,marginTop:2}}><span style={{fontSize:16,fontWeight:800,fontFamily:"'JetBrains Mono', monospace",color:color||T.tx}}>{value}</span>{d!=null&&<DB v={d} inv={inv}/>}</div>{sub&&<div style={{fontSize:9,color:T.t3,marginTop:1}}>{sub}</div>}</div>;}

function DatePicker({onSelect,color}){const[open,setOpen]=useState(false);const[start,setStart]=useState("");const[end,setEnd]=useState("");const label=start&&end?(new Date(start+"T00:00").toLocaleDateString("en-US",{month:"numeric",day:"numeric",year:"2-digit"})+" - "+new Date(end+"T00:00").toLocaleDateString("en-US",{month:"numeric",day:"numeric",year:"2-digit"})):"Custom";const active=start&&end;return(<div style={{position:"relative",display:"inline-block"}}><button onClick={()=>setOpen(!open)} style={{padding:"3px 10px",borderRadius:4,border:"1px solid "+(active?color:T.bd),background:active?color+"14":"transparent",color:active?color:T.t2,fontSize:9,fontWeight:600,cursor:"pointer",fontFamily:"'Outfit', sans-serif"}}>{label}</button>{open&&<div style={{position:"absolute",top:"100%",left:0,marginTop:4,padding:10,background:T.bg,border:"1px solid "+T.bd,borderRadius:6,zIndex:100,display:"flex",flexDirection:"column",gap:6,boxShadow:"0 8px 24px rgba(0,0,0,.4)"}}><div style={{display:"flex",gap:6,alignItems:"center"}}><div><div style={{fontSize:8,color:T.t3,marginBottom:2}}>Start</div><input type="date" value={start} onChange={e=>setStart(e.target.value)} style={{background:T.cd,border:"1px solid "+T.bd,borderRadius:4,color:T.tx,padding:"4px 6px",fontSize:10,fontFamily:"'JetBrains Mono', monospace",outline:"none"}}/></div><span style={{color:T.t4,marginTop:12}}>to</span><div><div style={{fontSize:8,color:T.t3,marginBottom:2}}>End</div><input type="date" value={end} onChange={e=>setEnd(e.target.value)} style={{background:T.cd,border:"1px solid "+T.bd,borderRadius:4,color:T.tx,padding:"4px 6px",fontSize:10,fontFamily:"'JetBrains Mono', monospace",outline:"none"}}/></div></div><button onClick={()=>{if(start&&end){onSelect(start,end);setOpen(false);}}} style={{padding:"4px 10px",borderRadius:4,border:"none",background:color,color:"#fff",fontSize:10,fontWeight:600,cursor:"pointer",opacity:start&&end?1:.4}}>Apply</button></div>}</div>);}

