// DataTable with pagination
function DataTable({cols,rows,color,emptyMsg}){
  const[sk,setSk]=useState(cols.find(c=>c.ds)?.key||cols[1]?.key);
  const[sd,setSd]=useState("desc");
  const[pp,setPp]=useState(50);
  const[pg,setPg]=useState(0);
  const sorted=useMemo(()=>[...rows].sort((a,b)=>{const av=a[sk]||0,bv=b[sk]||0;return sd==="desc"?bv-av:av-bv;}),[rows,sk,sd]);
  const pageRows=sorted.slice(pg*pp,(pg+1)*pp);
  const totalPages=Math.ceil(sorted.length/pp);
  const tSort=k=>{if(sk===k)setSd(d=>d==="desc"?"asc":"desc");else{setSk(k);setSd("desc");setPg(0);}};
  if(!rows.length)return <div style={{padding:20,textAlign:"center",color:T.t3,fontSize:11}}>{emptyMsg||"No data"}</div>;
  return(<div>
    <div style={{maxHeight:480,overflowY:"auto",overflowX:"auto"}}>
      <div style={{display:"inline-grid",gridTemplateColumns:cols.map(c=>c.w||"1fr").join(" "),gap:0,padding:"4px 12px",borderBottom:"2px solid "+T.bd,background:T.bg2,position:"sticky",top:0,zIndex:2,minWidth:"100%"}}>
        {cols.map((c,i)=><div key={i} onClick={c.ns?undefined:()=>tSort(c.key)} style={{cursor:c.ns?"default":"pointer",fontSize:8,fontWeight:600,color:sk===c.key?color:T.t3,textTransform:"uppercase",letterSpacing:.3,textAlign:c.al||(i===0?"left":"right"),padding:"0 3px",userSelect:"none",whiteSpace:"nowrap"}}>{c.label}{sk===c.key?(sd==="desc"?" \u2193":" \u2191"):""}</div>)}
      </div>
      {pageRows.map((row,ri)=><div key={ri} style={{display:"inline-grid",gridTemplateColumns:cols.map(c=>c.w||"1fr").join(" "),gap:0,padding:"4px 12px",borderBottom:"1px solid "+T.bd,alignItems:"center",minWidth:"100%"}}>
        {cols.map((c,ci)=><div key={ci} style={{fontSize:10,fontFamily:ci>0?"'JetBrains Mono', monospace":"'Outfit', sans-serif",fontWeight:ci===0?600:400,color:c.color?c.color(row):(ci===0?T.tx:T.t1),textAlign:c.al||(ci===0?"left":"right"),padding:"0 3px",whiteSpace:"nowrap",overflow:"hidden",textOverflow:"ellipsis"}}>{c.render?c.render(row):row[c.key]}</div>)}
      </div>)}
    </div>
    {/* Pagination */}
    <div style={{display:"flex",justifyContent:"flex-end",alignItems:"center",gap:8,padding:"6px 12px",borderTop:"1px solid "+T.bd,background:T.bg2}}>
      <span style={{fontSize:9,color:T.t3}}>Showing {pg*pp+1}–{Math.min((pg+1)*pp,sorted.length)} of {sorted.length}</span>
      {totalPages>1&&<div style={{display:"flex",gap:2}}>
        <button onClick={()=>setPg(Math.max(0,pg-1))} disabled={pg===0} style={{padding:"2px 6px",borderRadius:3,border:"1px solid "+T.bd,background:"transparent",color:pg===0?T.t4:T.t2,fontSize:9,cursor:pg===0?"default":"pointer"}}>&lt;</button>
        <span style={{fontSize:9,color:T.t2,padding:"2px 4px"}}>{pg+1}/{totalPages}</span>
        <button onClick={()=>setPg(Math.min(totalPages-1,pg+1))} disabled={pg>=totalPages-1} style={{padding:"2px 6px",borderRadius:3,border:"1px solid "+T.bd,background:"transparent",color:pg>=totalPages-1?T.t4:T.t2,fontSize:9,cursor:pg>=totalPages-1?"default":"pointer"}}>&gt;</button>
      </div>}
      <select value={pp} onChange={e=>{setPp(Number(e.target.value));setPg(0);}} style={{padding:"2px 4px",borderRadius:3,border:"1px solid "+T.bd,background:T.cd,color:T.t2,fontSize:9,cursor:"pointer",outline:"none"}}>
        {PAGE_OPTS.map(n=><option key={n} value={n}>{n} rows</option>)}
      </select>
    </div>
  </div>);
}

function Recs({camps,chConf,isAmz,isMeta}){const recs=useMemo(()=>{const r=[];camps.forEach(c=>{const nb7=c.nb?.roas7||0;const contrib=c.rev*chConf.margin-c.sp;if(isAmz&&c.acos>30&&nb7<2.5)r.push({sev:"crit",text:c.n+" ACOS "+pt(c.acos)+" / NB 7DC "+rx(nb7)+" — reduce bids or pause",impact:c.sp*.15});if(isAmz&&c.is&&c.is<25&&nb7>4)r.push({sev:"opp",text:c.n+" "+c.is+"% IS, NB 7DC "+rx(nb7)+" — increase budget",impact:c.rev*.2});if(c.bud&&c.sp/c.bud>.95)r.push({sev:"warn",text:c.n+" at "+Math.round(c.sp/c.bud*100)+"% budget cap",impact:c.rev*.1});if(contrib<0)r.push({sev:"crit",text:c.n+" contribution-negative ("+fm(contrib)+"/day)",impact:Math.abs(contrib)});if(isMeta&&c.hookRate&&c.hookRate<30)r.push({sev:"warn",text:c.n+" hook "+pt(c.hookRate)+" — refresh creative"});});return r.sort((a,b)=>(b.impact||0)-(a.impact||0)).slice(0,5);},[camps,chConf,isAmz,isMeta]);if(!recs.length)return null;const sc={crit:T.rd,warn:T.am,opp:T.cy};return(<div style={{padding:"10px 12px",background:T.cd,borderRadius:8,border:"1px solid "+T.bd,borderLeft:"3px solid "+T.am}}><div style={{fontSize:10,fontWeight:700,color:T.tx,textTransform:"uppercase",letterSpacing:.5,marginBottom:6}}>Recommendations ({recs.length})</div>{recs.map((r,i)=><div key={i} style={{fontSize:10,color:sc[r.sev]||T.t2,marginBottom:4,paddingLeft:8,borderLeft:"2px solid "+(sc[r.sev]||T.bd),lineHeight:1.5}}>{r.sev==="opp"&&<span style={{fontSize:8,padding:"1px 4px",borderRadius:2,background:T.cy+"20",color:T.cy,marginRight:4}}>OPP</span>}{r.text}{r.impact?<span style={{color:T.t3}}> ({fm(r.impact)}/d)</span>:null}</div>)}</div>);}

